From 4e94f711d9c2135e04c831186c124915ef938155 Mon Sep 17 00:00:00 2001
From: Scott Menzer <scott@id5.io>
Date: Thu, 8 Apr 2021 15:31:24 +0200
Subject: [PATCH] move reading and writing of the consent string hash for the
 user id module to after the gdpr checks. if no user id modules will be
 executed, this value isn't really necessary anyways.

---
 modules/userId/index.js | 15 ++++++++-------
 1 file changed, 8 insertions(+), 7 deletions(-)

diff --git a/modules/userId/index.js b/modules/userId/index.js
index be9883dae9c..3d910e2bc83 100644
--- a/modules/userId/index.js
+++ b/modules/userId/index.js
@@ -590,9 +590,6 @@ function refreshUserIds(options, callback) {
   initializeSubmodulesAndExecuteCallbacks(function() {
     let consentData = gdprDataHandler.getConsentData()

-    const storedConsentData = getStoredConsentData();
-    setStoredConsentData(consentData);
-
     // gdpr consent with purpose one is required, otherwise exit immediately
     let {userIdModules, hasValidated} = validateGdprEnforcement(submodules, consentData);
     if (!hasValidated && !hasGDPRConsent(consentData)) {
@@ -600,6 +597,10 @@ function refreshUserIds(options, callback) {
       return;
     }

+    // we always want the latest consentData stored, even if we don't execute any submodules
+    const storedConsentData = getStoredConsentData();
+    setStoredConsentData(consentData);
+
     let callbackSubmodules = [];
     for (let submodule of userIdModules) {
       if (submoduleNames.length > 0 &&
@@ -689,10 +690,6 @@ function populateSubmoduleId(submodule, consentData, storedConsentData, forceRef
  * @returns {SubmoduleContainer[]} initialized submodules
  */
 function initSubmodules(submodules, consentData) {
-  // we always want the latest consentData stored, even if we don't execute any submodules
-  const storedConsentData = getStoredConsentData();
-  setStoredConsentData(consentData);
-
   // gdpr consent with purpose one is required, otherwise exit immediately
   let { userIdModules, hasValidated } = validateGdprEnforcement(submodules, consentData);
   if (!hasValidated && !hasGDPRConsent(consentData)) {
@@ -700,6 +697,10 @@ function initSubmodules(submodules, consentData) {
     return [];
   }

+  // we always want the latest consentData stored, even if we don't execute any submodules
+  const storedConsentData = getStoredConsentData();
+  setStoredConsentData(consentData);
+
   return userIdModules.reduce((carry, submodule) => {
     populateSubmoduleId(submodule, consentData, storedConsentData, false);
     carry.push(submodule);
